<template>
  <section><div class="page-heading"><div><p class="eyebrow">المحاسبة</p><h1>الدفتر المالي</h1></div></div><div class="stats"><div class="stat-card"><span>💵</span><small>إجمالي المبيعات</small><strong>{{ money(sales) }}</strong></div><div class="stat-card"><span>🧾</span><small>إجمالي المصروفات</small><strong>{{ money(expenses) }}</strong></div><div class="stat-card"><span>📈</span><small>صافي التشغيل</small><strong>{{ money(sales-expenses) }}</strong></div></div><div class="panel"><div class="panel-title"><h2>دفتر اليومية</h2></div><table><thead><tr><th>النوع</th><th>المبلغ</th><th>التاريخ</th></tr></thead><tbody><tr v-for="e in entries" :key="e._id"><td>{{ e.type==='sale'?'مبيعات':'مصروف' }}</td><td>{{ money(e.total ?? e.amount) }}</td><td>{{ e.created_at ?? e.date }}</td></tr></tbody></table></div></section>
</template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import db from '../services/pouchdb';const sales=ref(0),expenses=ref(0),entries=ref<any[]>([]);const money=(v:number)=>new Intl.NumberFormat('ar-YE',{style:'currency',currency:'YER',maximumFractionDigits:0}).format(v);onMounted(async()=>{const s=await db.list<any>('sale'),e=await db.list<any>('expense');sales.value=s.reduce((n,x)=>n+Number(x.total||0),0);expenses.value=e.reduce((n,x)=>n+Number(x.amount||0),0);entries.value=[...s,...e].sort((a,b)=>String(b.created_at||b.date).localeCompare(String(a.created_at||a.date)))})</script>
